(()=>{const e=document.querySelector("[data-fixed-cta]"),t=document.querySelectorAll("[data-hide-fixed-cta]");if(e&&t.length&&"IntersectionObserver"in window){const r=new Set,a=new IntersectionObserver(t=>{t.forEach(e=>{e.isIntersecting?r.add(e.target):r.delete(e.target)}),e.classList.toggle("fixed-cta--hidden",r.size>0)});t.forEach(e=>a.observe(e))}!window.matchMedia("(prefers-reduced-motion: reduce)").matches&&window.gsap&&window.ScrollTrigger&&(gsap.registerPlugin(ScrollTrigger),gsap.utils.toArray("[data-animate]").forEach(e=>{gsap.from(e,{y:24,opacity:0,duration:.6,ease:"power2.out",scrollTrigger:{trigger:e,start:"top 85%",once:!0}})}))})();